function validate([nums, k]) {
  if (nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 values.';
  if (nums.some(v => v < -1000000 || v > 1000000)) return 'Each value is between -10^6 and 10^6.';
  if (k < 2 || k > nums.length) return 'k is between 2 and nums.length.';
  return null;
}

