function minOperations(nums, k) {
  const side = [];
  let start = 0;
  // One half of the window: a binary heap of indexes plus the count and sum of its live values.
  // above(a, b) says index a belongs nearer the top; indexes before start are dropped once they surface.
  const makeHalf = (above) => {
    const items = [];
    const swap = (a, b) => ([items[a], items[b]] = [items[b], items[a]]);
    const removeTop = () => {
      swap(0, items.length - 1);
      items.pop();
      let parent = 0;
      while (true) {
        let next = parent;
        for (const child of [2 * parent + 1, 2 * parent + 2]) {
          if (child < items.length && above(items[child], items[next])) next = child;
        }
        if (next === parent) return;
        swap(parent, next);
        parent = next;
      }
    };
    const half = {
      count: 0,
      sum: 0,
      add(index) {
        items.push(index);
        let child = items.length - 1;
        while (child > 0 && above(items[child], items[(child - 1) >> 1])) {
          swap(child, (child - 1) >> 1);
          child = (child - 1) >> 1;
        }
        half.count++;
        half.sum += nums[index];
        side[index] = half;
      },
      top() {
        while (items[0] < start) removeTop();
        return items[0];
      },
      take() {
        const index = half.top();
        removeTop();
        half.count--;
        half.sum -= nums[index];
        return index;
      },
    };
    return half;
  };
  const low = makeHalf((a, b) => nums[a] > nums[b]);
  const high = makeHalf((a, b) => nums[a] < nums[b]);
  let best = Infinity;
  for (let i = 0; i < nums.length; i++) {
    start = i - k + 1;
    if (start > 0) {
      side[start - 1].count--;
      side[start - 1].sum -= nums[start - 1];
    }
    low.add(i);
    high.add(low.take());
    if (high.count > low.count) low.add(high.take());
    if (start >= 0) {
      const median = nums[low.top()];
      best = Math.min(best, median * low.count - low.sum + high.sum - median * high.count);
    }
  }
  return best;
}

