function minOperations(nums, k) {
  // Some best target is one of the window's own values, so try each of them on every window.
  let best = Infinity;
  for (let first = 0; first + k <= nums.length; first++) {
    for (let j = first; j < first + k; j++) {
      let cost = 0;
      for (let m = first; m < first + k; m++) cost += Math.abs(nums[m] - nums[j]);
      if (cost < best) best = cost;
    }
  }
  return best;
}

