function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? pick(1500, 2000) : pick(2, 9);
  const k = large ? [2, 3, 50, 999, 1000, n - 1, n][pick(0, 6)] : pick(2, n);
  // Narrow spreads make ties and zero answers common; the widest uses the full value range.
  const spread = [2, 10, 1000000][pick(0, 2)];
  return [Array.from({ length: n }, () => pick(-spread, spread)), k];
}
